meta._fnpw_page_css:
/* ============ homepage 2026 (hx-), page-scoped, becomes front-page.php ============ */
/* Spacing uses the global tokens only (--sec-md, --sec-sm, --sp-1..6). The hero h1 is the one display size on this page. */

/* The sitewide fixed noise overlay (body::before in global.css) sat over the hero image and, with the old marquee,
   stopped Chromium from reporting an LCP candidate on this page. It is switched off on the homepage only. */
body::before{display:none}

/* --- hero (restored to the 4 Nov design) --- */
.hx-hero{position:relative;min-height:92vh;display:flex;align-items:flex-start;background:var(--euc-deep);overflow:hidden}
.hx-hero-bg{position:absolute;inset:0;background:#EBF7F7}
.hx-hero-bg img{position:absolute;left:0;top:6%;width:100%;height:100%;object-fit:cover;object-position:15% 44%;opacity:1}
.hx-hero-bg::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(15,49,50,0.95) 0%,rgba(15,49,50,0.94) 12%,rgba(15,49,50,0.91) 20%,rgba(15,49,50,0.85) 27%,rgba(15,49,50,0.77) 33%,rgba(15,49,50,0.66) 39%,rgba(15,49,50,0.53) 44%,rgba(15,49,50,0.39) 49%,rgba(15,49,50,0.26) 53%,rgba(15,49,50,0.15) 57%,rgba(15,49,50,0.07) 61%,rgba(15,49,50,0.02) 65%,rgba(15,49,50,0) 68%),linear-gradient(180deg,rgba(15,49,50,.18) 0%,rgba(15,49,50,.1) 10%,rgba(15,49,50,.03) 20%,rgba(15,49,50,0) 28%,rgba(15,49,50,0) 66%,rgba(15,49,50,.08) 76%,rgba(15,49,50,.22) 86%,rgba(15,49,50,.38) 94%,rgba(15,49,50,.45) 100%)}
.hx-hero .cw{position:relative;padding-bottom:7rem;padding-top:clamp(6rem,20vh,11rem);width:100%}
/* Phones keep the original bottom-aligned layout and heavier scrim so the text stays legible over the bright sky */
@media(max-width:760px){.hx-hero{align-items:flex-end}.hx-hero-bg img{object-position:50% 44%;top:0}.hx-hero-bg::after{background:linear-gradient(90deg,rgba(15,49,50,.96) 0%,rgba(15,49,50,.9) 28%,rgba(15,49,50,.52) 46%,rgba(15,49,50,0) 66%),linear-gradient(180deg,rgba(15,49,50,.4) 0%,rgba(15,49,50,.15) 38%,rgba(15,49,50,.85) 100%)}.hx-hero .cw{padding-top:9rem;padding-bottom:5.5rem}}
.hx-kicker{display:inline-flex;align-items:center;gap:.6rem;color:var(--euc-soft);font-family:var(--ff-d);font-size:.78rem;letter-spacing:.22em;text-transform:uppercase;margin-bottom:1.4rem}
.hx-kicker::before{content:"";width:2.2rem;height:2px;background:var(--euc-soft)}
.hx-h1{font-family:var(--ff-d);font-weight:800;font-size:clamp(2.6rem,6.5vw,5.4rem);line-height:1.02;letter-spacing:-.03em;color:var(--cream);max-width:13ch;margin:0 0 1.4rem}
.hx-h1 .wild{color:var(--euc-soft)}
.hx-lede{color:rgba(250,246,242,.88);font-size:clamp(1.05rem,1.6vw,1.3rem);max-width:40ch;line-height:1.6;margin-bottom:2.2rem}
.hx-hero-cta{display:flex;gap:1rem;flex-wrap:wrap;align-items:center}
.hx-btn{font-family:var(--ff-d);font-weight:600;font-size:1rem;padding:1rem 2rem;border-radius:0;text-decoration:none;transition:transform .18s ease,box-shadow .18s ease;display:inline-block}
.hx-btn:hover{transform:translateY(-2px)}
.hx-btn-don{background:var(--waratah);color:var(--cream);box-shadow:0 10px 30px -10px rgba(194,55,71,.5)}
.hx-btn-ghost{border:1.5px solid rgba(250,246,242,.55);color:var(--cream)}
.hx-btn-ghost:hover{border-color:var(--cream);background:rgba(250,246,242,.08)}
/* organic bottom edge */
.hx-hero-curve{position:absolute;left:0;right:0;bottom:-1px;height:70px}
.hx-hero-curve svg{display:block;width:100%;height:100%}

.hx-h1{text-shadow:0 2px 26px rgba(15,49,50,.4)}
.hx-lede-w{max-width:52ch!important}

/* --- Give a Tree photo band (Christmas appeal, Nov 2026) --- */
.hx-gat{position:relative;background:var(--soil-deep);color:var(--cream);overflow:hidden}
.hx-gat-im{position:absolute;top:0;right:0;bottom:0;width:50%;background:var(--soil)}
.hx-gat-im img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 32%}
.hx-gat-im::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(36,25,20,1) 0%,rgba(36,25,20,.7) 9%,rgba(36,25,20,0) 24%)}
.hx-gat .cw{min-height:400px;display:flex;align-items:center;padding-top:var(--sec-md);padding-bottom:var(--sec-md)}
.hx-gat-bd{max-width:min(540px,calc(50vw - 4.5rem));display:flex;flex-direction:column;gap:1.1rem}
.hx-gat h2{font-family:var(--ff-d);font-weight:800;font-size:clamp(1.9rem,3vw,2.6rem);line-height:1.08;letter-spacing:-.02em;color:var(--cream);max-width:14ch}
.hx-gat p{margin:0;max-width:46ch;color:rgba(250,246,242,.88)}
.hx-gat-cta{display:flex;align-items:center;gap:1.4rem;flex-wrap:wrap;margin-top:.5rem}
.hx-gat-note{font-size:.88rem;color:rgba(250,246,242,.78)}
@media(max-width:760px){
  .hx-gat-im{position:relative;width:100%;height:260px}
  .hx-gat-im::after{background:linear-gradient(0deg,rgba(36,25,20,1) 0%,rgba(36,25,20,0) 40%)}
  .hx-gat .cw{min-height:0;padding-top:var(--sp-3);padding-bottom:var(--sec-md)}
  .hx-gat-bd{max-width:none}
}

/* --- doorways: why we exist, supporters and partners, Give a Tree strip --- */
.door-head{text-align:center;max-width:980px;margin:0 auto var(--sp-5)}
.door-head h2{max-width:26ch;margin-left:auto;margin-right:auto}
.door-head h2 em{font-style:normal;color:var(--euc)}
.door-g{display:grid;grid-template-columns:1fr 1fr;gap:var(--sp-3)}
.door-c{display:block;padding:var(--sp-4);border:1px solid var(--rule);background:var(--white);text-decoration:none;color:inherit;border-top:4px solid var(--waratah)}
.door-c2{background:var(--euc-deep);color:var(--cream);border-color:var(--euc-deep);border-top-color:var(--euc-mid)}
.door-k{font-size:.7rem;letter-spacing:.2em;text-transform:uppercase;font-weight:700;color:var(--euc)}
.door-c2 .door-k{color:var(--euc-soft)}
.door-c h3{margin:var(--sp-1) 0;color:var(--euc-deep)}
.door-c2 h3{color:var(--cream)}
.door-c p{font-size:.94rem;line-height:1.55;color:var(--char);margin:0 0 var(--sp-2)}
.door-c2 p{color:rgba(250,246,242,.85)}
.door-go{font-weight:700;font-size:.9rem;color:var(--euc)}
.door-c2 .door-go{color:var(--euc-soft)}
/* seasonal strip: thin band, sand background, same rhythm as .sec.strip */
.gat-strip{display:flex;align-items:center;justify-content:space-between;gap:var(--sp-3);flex-wrap:wrap;margin-top:var(--sp-3);padding:var(--sec-sm) var(--sp-4);background:var(--sand);border-left:4px solid var(--bark)}
.gat-strip p{margin:0;max-width:60ch;color:var(--char)}
.gat-strip strong{font-family:var(--ff-d);font-weight:700;color:var(--euc-deep)}
.gat-strip-act{display:flex;align-items:center;gap:var(--sp-2);flex-wrap:wrap}
.gat-note{font-size:.85rem;color:var(--stone);white-space:nowrap}
@media(max-width:760px){.door-head{margin-bottom:var(--sp-4)}.door-g{grid-template-columns:1fr;gap:var(--sp-2)}.door-c{padding:var(--sp-3)}.gat-strip{padding:var(--sp-3)}}

/* --- pillars --- */
.hx-pils-head{margin-bottom:var(--sp-5)}
.hx-pilrow{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--sp-4)}
.hx-pil{display:block;text-decoration:none;color:inherit}
.hx-pil-im{position:relative;aspect-ratio:4/3;overflow:hidden;background:var(--euc-pale)}
.hx-pil-im img{width:100%;height:100%;object-fit:cover;transition:transform .6s ease}
.hx-pil:hover .hx-pil-im img{transform:scale(1.04)}
.hx-pil-bar{display:block;width:46px;height:4px;margin:var(--sp-3) 0 var(--sp-2);background:var(--pilc,var(--euc))}
.hx-pil h3{color:var(--euc-deep);margin:0 0 var(--sp-1)}
.hx-pil p{font-size:.95rem;color:var(--char);max-width:38ch;margin:0 0 var(--sp-2)}
.hx-pil-go{display:inline-block;font-family:var(--ff-d);font-weight:600;font-size:.88rem;color:var(--euc);transition:transform .2s ease}
.hx-pil:hover .hx-pil-go{transform:translateX(4px)}
@media(max-width:920px){.hx-pilrow{grid-template-columns:1fr;gap:var(--sp-4)}.hx-pil{display:grid;grid-template-columns:104px 1fr;column-gap:var(--sp-3);row-gap:0;align-items:start}.hx-pil-im{aspect-ratio:1/1;grid-row:1/5}.hx-pil-bar{margin:0 0 var(--sp-1)}.hx-pil p{font-size:.9rem;margin-bottom:var(--sp-1)}}

/* --- impact band --- */
.hx-impact{overflow:hidden;padding-bottom:calc(var(--sec-md) + var(--sp-4))}
.hx-impact h2{max-width:24ch}
.hx-imp-lead{display:grid;grid-template-columns:repeat(3,1fr);gap:var(--sp-5);align-items:start;padding:var(--sp-4) 0;border-bottom:1px solid rgba(250,246,242,.18);margin-top:var(--sp-4)}
.hx-imp-ln{font-family:var(--ff-d);font-weight:800;font-size:clamp(2.4rem,4.6vw,3.9rem);letter-spacing:-.04em;line-height:.95;color:var(--euc-soft);white-space:nowrap}
.hx-imp-l p{font-size:1rem;color:rgba(250,246,242,.9);max-width:24ch;line-height:1.45;margin:var(--sp-1) 0 0}
.hx-imp-u{font-family:var(--ff-b);font-weight:600;font-size:.27em;color:var(--cream);margin-left:.18em;letter-spacing:0}
.hx-imp-ic{display:block;margin-bottom:var(--sp-2)}.hx-imp-ic img{height:52px;width:auto;display:block}
.hx-chip{display:inline-block;font-family:var(--ff-d);font-size:.66rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--cream);padding:.5em 1.2em;border-radius:0}
.hx-chip.pb-healing{background:var(--bark);color:var(--cream)}
.hx-imp-year-l{display:inline-flex;align-items:center;gap:.6em;font-family:var(--ff-b);font-size:.72rem;font-weight:700;letter-spacing:.22em;text-transform:uppercase;color:var(--cream);margin-top:var(--sp-4)}
.hx-imp-year-l::before{content:"";width:22px;height:1.5px;background:var(--cream);display:inline-block}
.hx-imp-g{display:grid;grid-template-columns:repeat(auto-fit,minmax(215px,1fr));gap:var(--sp-4);padding-top:var(--sp-3)}
.hx-imp-n{font-family:var(--ff-d);font-weight:700;font-size:clamp(1.7rem,2.6vw,2.3rem);letter-spacing:-.03em;color:var(--euc-soft);line-height:1;margin:var(--sp-2) 0 var(--sp-1)}
.hx-imp-i p{font-size:.95rem;color:rgba(250,246,242,.85);max-width:26ch;line-height:1.45;margin:0}
.hx-imp-src{margin-top:var(--sp-4);font-size:.85rem;color:rgba(250,246,242,.65)}
.hx-imp-src a{color:var(--euc-soft)}
.hx-impact-curve{position:absolute;left:0;right:0;bottom:-1px;height:56px}
.hx-impact-curve svg{display:block;width:100%;height:100%}
@media(max-width:820px){.hx-imp-lead{grid-template-columns:1fr;gap:var(--sp-3)}.hx-imp-l{display:grid;grid-template-columns:52px 1fr;column-gap:var(--sp-2);align-items:center}.hx-imp-ic{grid-row:1/3;margin:0}.hx-imp-ic img{height:44px}.hx-imp-l p{margin-top:0}.hx-imp-g{grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:var(--sp-3)}.hx-chip{font-size:.6rem}}

/* --- flagship projects --- */
.hx-rail-head{display:flex;justify-content:space-between;align-items:flex-end;gap:var(--sp-4);flex-wrap:wrap;margin-bottom:var(--sp-4)}
.hx-rail-lede{font-size:1rem;line-height:1.6;color:var(--char);max-width:52ch;margin:var(--sp-2) 0 0}
.fl-im{position:relative;aspect-ratio:4/3;overflow:hidden;background:var(--euc-pale)}
.fl-im img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .7s ease}
.fl-card:hover .fl-im img{transform:scale(1.05)}
.fl-chip{position:absolute;top:var(--sp-1);left:var(--sp-1);font-size:.64rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;padding:.4em .8em;color:var(--cream)}
.fl-parks{background:var(--euc)}.fl-species{background:var(--waratah)}.fl-healing{background:var(--soil)}
.fl-loc{position:absolute;bottom:var(--sp-1);left:var(--sp-1);background:rgba(250,246,242,.92);color:var(--euc-deep);font-family:var(--ff-d);font-size:.72rem;font-weight:600;letter-spacing:.04em;padding:.4em 1em}
.fl-card{display:flex;flex-direction:column;text-decoration:none;color:inherit;background:var(--white);border:1px solid var(--rule)}
.fl-bd{padding:var(--sp-3);display:flex;flex-direction:column;flex:1}
.fl-bd h3{color:var(--euc-deep);line-height:1.2;margin:0 0 var(--sp-1)}
.fl-bd p{font-size:.88rem;line-height:1.5;color:var(--char);margin:0 0 var(--sp-2);flex:1}
.fl-go{font-size:.82rem;font-weight:600;color:var(--euc)}
.fls-wrap{position:relative}
.fls-track{display:flex;gap:var(--sp-3);overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;padding:var(--sp-1) 0 var(--sp-2);scrollbar-width:none}
.fls-track::-webkit-scrollbar{display:none}
.fls-track .fl-card{flex:0 0 calc((100% - 3*var(--sp-3))/4);scroll-snap-align:start}
@media(max-width:1100px){.fls-track .fl-card{flex-basis:calc((100% - 2*var(--sp-3))/3)}}
@media(max-width:820px){.fls-track .fl-card{flex-basis:calc((100% - var(--sp-3))/2)}}
@media(max-width:520px){.fls-track .fl-card{flex-basis:82%}}
.fls-bar{display:flex;align-items:center;gap:var(--sp-3);margin-top:var(--sp-2)}
.fls-prog{flex:1;height:3px;background:var(--rule);position:relative;overflow:hidden}
.fls-prog i{position:absolute;left:0;top:0;bottom:0;background:var(--euc-deep);width:33%;transition:left .3s ease,width .3s ease}
.fls-count{font-family:var(--ff-d);font-size:.86rem;font-weight:600;color:var(--euc-deep);min-width:5.5ch;text-align:right}
.fls-btn{width:48px;height:48px;border:1.5px solid var(--euc-deep);background:transparent;color:var(--euc-deep);font-size:1.15rem;cursor:pointer;transition:background .2s,color .2s,opacity .2s}
.fls-btn:hover{background:var(--euc-deep);color:var(--cream)}
.fls-btn[disabled]{opacity:.3;cursor:default;background:transparent;color:var(--euc-deep)}

/* --- partner & invest (landscape band, photo with deep scrim) --- */
.hx-pt{position:relative;overflow:hidden;color:var(--cream);padding:var(--sec-md) 0;min-height:max(760px,52vw);display:flex;align-items:flex-end}
.hx-pt-bg{position:absolute;inset:0;z-index:0;width:100%;height:100%;object-fit:cover;object-position:50% 55%;display:block}
.hx-pt::before{content:"";position:absolute;inset:0;z-index:1;background:linear-gradient(90deg,rgba(15,49,50,.92) 0%,rgba(15,49,50,.8) 30%,rgba(15,49,50,.35) 46%,rgba(15,49,50,0) 58%),linear-gradient(0deg,rgba(15,49,50,.9) 0%,rgba(15,49,50,.6) 14%,rgba(15,49,50,0) 32%)}
.hx-pt .cw{position:relative;z-index:2;width:100%}
.hx-pt-cap{position:absolute;right:var(--sp-2);top:var(--sp-2);z-index:2;font-size:.72rem;opacity:.75}
.hx-pt .ey{color:var(--euc-pale)}.hx-pt .ey::before{background:var(--euc-pale)}
.hx-pt h2{color:var(--cream);max-width:15ch}
.hx-pt .lede{color:rgba(250,246,242,.9);max-width:46ch;margin-top:var(--sp-3)}
.hx-pt-acts{display:flex;gap:var(--sp-3);align-items:center;flex-wrap:wrap;margin-top:var(--sp-4)}
.hx-pt-btn{display:inline-flex;align-items:center;padding:1.05em 2em;font-family:var(--ff-d);font-weight:700;font-size:.9rem;text-decoration:none;background:var(--cream);color:var(--euc-deep);border:1.5px solid var(--cream);transition:background .18s}
.hx-pt-btn:hover{background:var(--euc-pale);border-color:var(--euc-pale)}
.hx-pt-talk{font-family:var(--ff-d);font-weight:700;color:var(--cream);text-decoration:none;border-bottom:2px solid currentColor;padding-bottom:.15em}
.hx-pt-talk:hover{color:var(--euc-pale)}
.hx-pt-routes{display:grid;grid-template-columns:repeat(3,1fr);margin-top:var(--sp-6);border-top:1px solid rgba(250,246,242,.3)}
.hx-pt-routes a{display:flex;justify-content:space-between;gap:var(--sp-2);padding:var(--sp-3) var(--sp-3) 0 0;color:var(--cream);text-decoration:none;border-right:1px solid rgba(250,246,242,.18)}
.hx-pt-routes a+a{padding-left:var(--sp-3)}.hx-pt-routes a:last-child{border-right:0}
.hx-pt-routes a:hover b{color:var(--euc-pale)}
.hx-pt-routes b{font-family:var(--ff-d);font-size:1.12rem;display:block;margin-bottom:var(--sp-1)}
.hx-pt-routes span{font-size:.9rem;opacity:.85;line-height:1.5}
@media(max-width:900px){
  .hx-pt{min-height:0;display:block}.hx-pt-bg{object-position:72% 30%}
  .hx-pt::before{background:linear-gradient(0deg,rgba(15,49,50,.94) 0%,rgba(15,49,50,.84) 60%,rgba(15,49,50,.6) 100%)}
  .hx-pt-cap{left:var(--sp-2);right:auto;top:auto;bottom:var(--sp-1)}
  .hx-pt-routes{grid-template-columns:1fr;margin-top:var(--sp-5)}
  .hx-pt-routes a,.hx-pt-routes a+a{border-right:0;border-bottom:1px solid rgba(250,246,242,.18);padding:var(--sp-3) 0}
  .hx-pt-routes a:last-child{border-bottom:0;padding-bottom:0}
}

/* --- since 1970: story and Impact Report, one section --- */
.hx-story .two{grid-template-columns:.8fr 1.2fr;gap:clamp(var(--sp-5),6vw,var(--sp-6))}
.hx-ir-cov{position:relative;justify-self:center;width:min(330px,84%)}
.hx-ir-cov img{position:relative;z-index:1;display:block;width:100%;height:auto;box-shadow:12px 12px 0 var(--euc-deep);transition:transform .3s ease,box-shadow .3s ease}
.hx-ir-cov:hover img{transform:translate(-4px,-4px);box-shadow:18px 18px 0 var(--euc-deep)}
.hx-story p{max-width:52ch;margin:0 0 var(--sp-2)}
.hx-story .ey + h2{margin-bottom:var(--sp-3)}
.hx-story .hx-quote{margin-top:var(--sp-4)}
.hx-story-acts{display:flex;gap:var(--sp-2);flex-wrap:wrap;align-items:center;margin-top:var(--sp-4)}
.hx-story-more{margin-top:var(--sp-3)}
.hx-ir-trust{display:flex;gap:var(--sp-4);flex-wrap:wrap;margin-top:var(--sp-4);padding-top:var(--sp-3);border-top:1px solid var(--rule);font-size:.92rem;font-weight:500;color:var(--char)}
.hx-ir-trust span{display:inline-flex;align-items:center;gap:.45em}
.hx-ir-trust i{font-style:normal;color:var(--euc-deep);font-weight:700}
@media(max-width:880px){.hx-story .two{grid-template-columns:1fr;gap:var(--sp-4)}.hx-ir-cov{width:min(170px,50%);justify-self:start}.hx-story .hx-quote{margin-top:var(--sp-3)}}

/* --- newsletter strip --- */
.hx-news{border-top:1px solid var(--rule)}
.hx-news-g{display:grid;grid-template-columns:1fr auto;gap:clamp(var(--sp-4),4vw,var(--sp-6));align-items:center}
.hx-news-g p{max-width:68ch;margin:var(--sp-3) 0 0}
.hx-news-g .btn-p{min-width:250px;white-space:nowrap}
@media(max-width:820px){.hx-news-g{grid-template-columns:1fr;gap:var(--sp-4)}}
main:has(.hx-news)+.ftr{margin-top:0}

/* --- shared --- */
a:focus-visible,button:focus-visible{outline:2px solid var(--euc);outline-offset:3px}
@media(prefers-reduced-motion:reduce){
  .hx-pil-im img,.fl-im img,.hx-ir-cov img,.hx-pil-go{transition:none}
}

/* Homepage option preview (Nov 2026) */
.door-g .door-c{padding:var(--sp-3) var(--sp-4)}
.door-g .door-c h3{font-size:1.2rem;margin:.3rem 0 .35rem}
.door-g .door-c p{font-size:.9rem;line-height:1.5;margin:0 0 .7rem}
@media(min-width:861px){.hx-feat3 .fls-track{overflow:visible}.hx-feat3 .fls-track .fl-card{flex:1 1 0}.hx-feat3 .fls-bar{display:none}}
.hx-h1{max-width:17ch;font-size:clamp(2.3rem,5vw,4.2rem);line-height:1.05}
.hx-btn-lt{background:var(--cream);color:var(--euc-deep)}
