(function(){
  var lm=document.getElementById('lmq'), lb=document.getElementById('lmqBtn');
  if(lm&&lb){lb.addEventListener('click',function(){var p=lm.classList.toggle('paused');lb.dataset.state=p?'paused':'';lb.querySelector('.lmq-tx').textContent=p?'Play':'Pause';lb.setAttribute('aria-label',p?'Play partner logos':'Pause partner logos');});}
  var tabs=[].slice.call(document.querySelectorAll('.wt'));
  function pick(t){
    tabs.forEach(function(x){var on=x===t;x.setAttribute('aria-selected',on?'true':'false');x.tabIndex=on?0:-1;});
    document.querySelectorAll('.wpn').forEach(function(p){p.hidden=p.id!==t.getAttribute('aria-controls')});
  }
  tabs.forEach(function(t,i){
    t.addEventListener('click',function(){pick(t)});
    t.addEventListener('keydown',function(e){
      var n=null;
      if(e.key==='ArrowRight')n=tabs[(i+1)%tabs.length]; else if(e.key==='ArrowLeft')n=tabs[(i-1+tabs.length)%tabs.length];
      else if(e.key==='Home')n=tabs[0]; else if(e.key==='End')n=tabs[tabs.length-1];
      if(n){e.preventDefault();n.focus();pick(n)}
    });
  });
})();

