(function(){

  // Where we run: one panel at a time, switched by the state tabs.
  var wt = document.getElementById('vwTabs');
  if (wt) {
    var panels = [].slice.call(document.querySelectorAll('.vw-p'));
    wt.addEventListener('click', function (e) {
      var b = e.target.closest('button');
      if (!b) return;
      Array.prototype.forEach.call(wt.children, function (x) {
        x.setAttribute('aria-selected', x === b ? 'true' : 'false');
      });
      panels.forEach(function (p) { p.hidden = p.dataset.s !== b.dataset.s; });
      var sel = document.getElementById('vf-state');
      if (sel) sel.value = b.dataset.s;
    });
    wt.addEventListener('keydown', function (e) {
      if (e.key !== 'ArrowRight' && e.key !== 'ArrowLeft') return;
      var tabs = [].slice.call(wt.children);
      var i = tabs.indexOf(document.activeElement);
      if (i < 0) return;
      e.preventDefault();
      var n = tabs[(i + (e.key === 'ArrowRight' ? 1 : tabs.length - 1)) % tabs.length];
      n.focus(); n.click();
    });
  }
  // sticky bar: show once the hero is gone, hide over the enquiry form
  var bar=document.getElementById('vSticky'), hero=document.querySelector('.fb-hero'), cta=document.getElementById('enquire');
  if(bar&&hero&&'IntersectionObserver' in window){
    var pastHero=false, atForm=false;
    function paint(){ bar.classList.toggle('on', pastHero && !atForm); }
    new IntersectionObserver(function(es){ pastHero=!es[0].isIntersecting; paint(); },{threshold:0}).observe(hero);
    if(cta) new IntersectionObserver(function(es){ atForm=es[0].isIntersecting; paint(); },{threshold:0}).observe(cta);
  }
})();

