(function(){
  var tabs=document.querySelectorAll('.jt');
  function pick(id){
    tabs.forEach(function(t){t.setAttribute('aria-selected',t.dataset.j===id?'true':'false')});
    document.querySelectorAll('.jp').forEach(function(p){p.hidden=p.id!=='jp-'+id});
  }
  tabs.forEach(function(t,i){
    t.addEventListener('click',function(){pick(t.dataset.j)});
    t.addEventListener('keydown',function(e){
      var k=e.key, n=null;
      if(k==='ArrowRight')n=tabs[(i+1)%tabs.length]; else if(k==='ArrowLeft')n=tabs[(i-1+tabs.length)%tabs.length];
      if(n){e.preventDefault();n.focus();pick(n.dataset.j)}
    });
  });
})();
/*__FNPW_SCRIPT__*/
(function(){
  document.querySelectorAll('.jd-more').forEach(function(b){
    b.addEventListener('click',function(){
      var open=b.getAttribute('aria-expanded')!=='true';
      document.querySelectorAll('[data-more="'+b.dataset.for+'"]').forEach(function(el){el.hidden=!open});
      b.setAttribute('aria-expanded',open?'true':'false');
      b.textContent=open?b.dataset.less:b.dataset.label;
    });
  });
})();

