.hc-stat b{font-family:var(--ff-d);color:var(--euc-deep);font-weight:700}

.nw-hero{background:var(--euc-deep);padding:clamp(3rem,6vw,4.6rem) 0 clamp(2.4rem,4vw,3.2rem)}
.nw-hero .ey{color:var(--euc-soft)}
.nw-hero h1{color:var(--cream);font-size:clamp(1.9rem,4.4vw,3rem);font-weight:600;letter-spacing:-.028em;line-height:1.07;margin:1rem 0 1.1rem;max-width:20ch}
.nw-hero .lede{color:rgba(250,246,242,.88);max-width:56ch}
.nw-crumb{display:flex;gap:.5em;font-size:.8rem;color:rgba(250,246,242,.72);margin-bottom:1.4rem}
.nw-crumb a{color:var(--euc-soft)}
.nw-list{border-top:1px solid var(--rule);margin-top:2rem}
.nw-row{display:grid;grid-template-columns:9rem 1fr auto;gap:1.5rem;align-items:baseline;padding:1.35rem 0;border-bottom:1px solid var(--rule);transition:.2s}
.nw-row:hover{background:var(--sand)}
.nw-date{font-size:.74rem;letter-spacing:.15em;text-transform:uppercase;font-weight:700;color:var(--stone)}
.nw-pub{font-family:var(--ff-d);font-weight:600;font-size:1.05rem;color:var(--euc-deep);margin:0 0 .3rem}
.nw-blurb{font-size:.92rem;line-height:1.55;color:var(--char);margin:0;max-width:62ch}
.nw-go{font-size:.8rem;font-weight:700;color:var(--euc);white-space:nowrap}
@media(max-width:720px){
  .nw-row{grid-template-columns:1fr;gap:.4rem}
  .nw-go{margin-top:.3rem}
}

.me-sec{padding:var(--sec-md) 0;background:var(--cream)}
.me-g{display:grid;grid-template-columns:.9fr 1.1fr;gap:clamp(2rem,5vw,3.5rem);align-items:start}
@media(max-width:900px){.me-g{grid-template-columns:1fr;gap:2rem}}
.me-g p{font-size:1.02rem;line-height:1.72;color:var(--char);margin-bottom:1rem;max-width:54ch}
.me-contact{display:flex;flex-direction:column;gap:.7rem;margin-top:1.6rem;padding-top:1.4rem;border-top:1px solid var(--rule)}
.me-contact a{display:flex;align-items:center;gap:.6em;font-family:var(--ff-d);font-weight:600;
  font-size:1.02rem;color:var(--euc-deep);text-decoration:none}
.me-contact a:hover{color:var(--euc);opacity:1}
.me-contact svg{width:17px;height:17px;flex:0 0 17px;stroke:var(--euc);fill:none;stroke-width:2}
.hsform{background:var(--white);border:1px solid var(--rule);padding:1.8rem}
@media(max-width:600px){.hsform{padding:1.3rem 1.1rem}}
.hsform h3{font-size:1.12rem;color:var(--euc-deep);margin:0 0 1.2rem}
.hsform-slot{min-height:220px}
.hsform-slot iframe{width:100%!important;border:0;display:block}
.hsform-fallback{margin:1rem 0 0;font-size:.88rem;line-height:1.6;color:var(--char)}
.hsform-fallback a{color:var(--euc-deep);font-weight:700;border-bottom:1px solid currentColor}
.hsform .me-small{margin:1rem 0 0;font-size:.78rem;color:var(--stone);line-height:1.5}

/* ===== Our Impact page, rebuilt Oct 2026 (design: Impact Page Wireframes, artboard F) ===== */
main section[id]{scroll-margin-top:140px}
.ip-head{max-width:780px}
.ip-head .lede{margin-top:var(--sp-3)}
.ip-headrow{display:flex;flex-wrap:wrap;gap:var(--sp-2) var(--sp-5);justify-content:space-between;align-items:flex-end;margin-bottom:var(--sp-5)}
.ip-note{font-size:.9rem;color:var(--stone);max-width:32ch}
.ip-acts{display:flex;flex-wrap:wrap;gap:var(--sp-2);align-items:center}
.ip-btn-c{background:var(--cream);color:var(--euc-deep);border-color:var(--cream)}
.ip-btn-c:hover{background:var(--euc-soft);border-color:var(--euc-soft);color:var(--euc-deep);opacity:1}
.ip-btn-oc{background:transparent;color:var(--cream);border-color:var(--euc-soft)}
.ip-btn-oc:hover{background:var(--cream);color:var(--euc-deep);opacity:1}
.ip-arrow::after{content:"→";font-weight:700}

/* hero */
.ip-hero{position:relative;isolation:isolate;overflow:hidden;background:var(--euc-deep);color:var(--cream);min-height:min(70vh,640px);display:flex;align-items:flex-end;padding:var(--hero-top) 0 var(--hero-bot)}
.ip-hero::before{content:"";position:absolute;inset:0;z-index:-2;background:url('https://elyciap.github.io/fnpw-website-2026/assets/img/impact-hero-coast.jpg') center/cover;background-image:image-set(url('https://elyciap.github.io/fnpw-website-2026/assets/img/r/impact-hero-coast-1600.webp') type('image/webp'),url('https://elyciap.github.io/fnpw-website-2026/assets/img/impact-hero-coast.jpg') type('image/jpeg'))}
.ip-hero::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(90deg,rgba(15,49,50,.94) 0%,rgba(15,49,50,.86) 42%,rgba(15,49,50,.35) 66%,rgba(15,49,50,0) 85%)}
.ip-hero .cw{width:100%}
.ip-crumb{display:flex;gap:.5em;font-size:.82rem;margin-bottom:var(--sp-4);color:rgba(250,246,242,.75)}
.ip-crumb a{color:rgba(250,246,242,.75)}
.ip-hero-in{max-width:720px;display:flex;flex-direction:column;gap:var(--sp-3)}
.ip-badge{position:absolute;top:0;right:clamp(1.25rem,4vw,2.5rem);width:clamp(64px,9vw,132px);height:auto;display:block}
.ip-hero .ey{color:var(--euc-mid)}
.ip-year{font-family:var(--ff-d);font-weight:800;font-size:clamp(2.8rem,5vw,4.4rem);line-height:.9;letter-spacing:-.04em;color:var(--euc-mid);white-space:nowrap}
.ip-year span{color:var(--euc-soft)}

.ip-hero h1{color:var(--cream);font-size:clamp(1.8rem,3.2vw,2.7rem);line-height:1.12;max-width:24ch}
.ip-hero .lede{color:rgba(250,246,242,.9);max-width:52ch}
@media(max-width:860px){.ip-hero::after{background:linear-gradient(180deg,rgba(15,49,50,.72) 0%,rgba(15,49,50,.92) 100%)}}

/* on-this-page bar */
.ip-jump{position:sticky;top:73px;z-index:30;background:var(--euc-deep)}
.ip-jump .cw{display:flex;align-items:center;gap:var(--sp-1);overflow-x:auto;white-space:nowrap;min-height:56px}
.ip-jump-l{font-size:.75rem;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--euc-mid);margin-right:var(--sp-2)}
.ip-jump a{color:var(--cream);font-weight:600;font-size:.92rem;padding:.55rem .9rem;border-radius:999px}
.ip-jump a:hover{background:rgba(198,235,202,.16);opacity:1}
.ip-jump a.ip-jcta{margin-left:auto;background:var(--euc-soft);color:var(--euc-deep);border-radius:0;padding:.6rem 1.1rem}
.ip-jump a.ip-jcta:hover{background:var(--cream)}

/* 2025 results */
.ip-results{background:var(--white)}
.ip-g6{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;background:var(--rule);border:1px solid var(--rule)}
.ip-g6 > div{background:var(--white);padding:var(--sp-4);display:flex;flex-direction:column;gap:var(--sp-1)}
.ip-c{font-size:.75rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.ip-n{font-family:var(--ff-d);font-weight:800;font-size:clamp(2.6rem,4.6vw,4rem);line-height:1;letter-spacing:-.04em;color:var(--euc)}
.ip-l{font-size:1rem;line-height:1.4;color:var(--char);max-width:26ch}
@media(max-width:860px){.ip-g6{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:520px){.ip-g6{grid-template-columns:1fr}}
.ip-rpt{display:grid;grid-template-columns:150px minmax(0,1fr);gap:clamp(2.5rem,5vw,4.5rem);align-items:center;background:var(--hovea-deep);color:var(--cream);padding:clamp(1.4rem,2.6vw,2rem) clamp(1.5rem,3vw,2.5rem);margin-top:var(--sp-5)}
.ip-rpt img{display:block;width:100%;height:auto;box-shadow:0 18px 34px -14px rgba(0,0,0,.6)}
.ip-rpt .ey{color:var(--hovea-soft)}
.ip-rpt h3{color:var(--cream);font-size:clamp(1.4rem,2.2vw,1.9rem);margin-top:var(--sp-1)}
.ip-rpt p{color:rgba(250,246,242,.88);max-width:56ch;margin-top:var(--sp-2)}
.ip-rpt .ip-acts{margin-top:var(--sp-3)}
.ip-rpt .ip-acts .ip-btn-oc{border-color:var(--hovea-soft)}
.ip-rpt small{display:block;margin-top:var(--sp-2);font-size:.86rem;color:var(--hovea-soft)}
@media(max-width:600px){.ip-rpt{grid-template-columns:1fr}.ip-rpt img{max-width:140px}}

/* case studies */
.ip-cs{background:var(--bg);color:var(--fg)}
.ip-cs + .ip-cs{margin-top:var(--sp-4)}
.ip-cs-main{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,7fr)}
.ip-cs-rev .ip-cs-main{grid-template-columns:minmax(0,7fr) minmax(0,5fr)}
.ip-cs-rev .ip-cs-img{order:2}
.ip-cs-img{position:relative;min-height:340px;overflow:hidden}
.ip-cs-img img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:block}
.ip-cs-tag{position:absolute;left:0;top:var(--sp-4);background:var(--bg);color:var(--fg);font-family:var(--ff-d);font-weight:700;font-size:.92rem;padding:.6rem 1.1rem .6rem 1.5rem}
.ip-cs-rev .ip-cs-tag{left:auto;right:0;padding:.6rem 1.5rem .6rem 1.1rem}
.ip-cs-body{padding:clamp(1.75rem,3vw,2.25rem) clamp(1.75rem,4vw,3.5rem);display:flex;flex-direction:column;justify-content:center}
.ip-cs-k{font-size:.75rem;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:var(--ac)}
.ip-cs-n{font-family:var(--ff-d);font-weight:800;font-size:clamp(3.25rem,5vw,4.5rem);line-height:.95;letter-spacing:-.045em;color:var(--ac);margin-top:var(--sp-2)}
.ip-cs-n small{font-family:var(--ff-b);font-size:1.3rem;font-weight:700;letter-spacing:0;margin-left:.3em}
.ip-cs-nl{font-weight:600;color:var(--fg);margin-top:var(--sp-1)}
.ip-cs h3{color:var(--fg);margin-top:var(--sp-2);font-size:clamp(1.35rem,2.1vw,1.85rem)}
.ip-cs-body p{color:var(--sub);margin-top:var(--sp-2);max-width:62ch}
.ip-cs-body p.ip-cs-with{font-size:.88rem;border-top:1px solid var(--line);padding-top:var(--sp-2);margin-top:var(--sp-3)}
.ip-cs-with strong{color:var(--fg)}
.ip-cs-link{align-self:flex-start;margin-top:var(--sp-3);color:var(--fg);font-weight:700;border-bottom:2px solid var(--ac);padding-bottom:3px}
.ip-cs-link:hover{color:var(--fg);opacity:1;border-bottom-width:4px}
.ip-cs-more{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));border-top:1px solid var(--line)}
.ip-cs-mini{padding:var(--sp-2) clamp(1.75rem,4vw,3.5rem);border-right:1px solid var(--line);display:grid;grid-template-columns:8.5rem minmax(0,1fr);column-gap:var(--sp-3);row-gap:.2rem;align-items:start;align-content:start}
.ip-cs-mini .ip-cs-mn{grid-row:1/3}
.ip-cs-mini:last-child{border-right:0}
.ip-cs-mini .ip-cs-mn{font-family:var(--ff-d);font-weight:800;font-size:1.4rem;letter-spacing:-.03em;line-height:1.2;color:var(--ac)}
.ip-cs-mini strong{font-family:var(--ff-d);color:var(--fg)}
.ip-cs-mini span:not(.ip-cs-mn){font-size:.88rem;line-height:1.45;color:var(--sub)}
@media(max-width:900px){.ip-cs-main,.ip-cs-rev .ip-cs-main{grid-template-columns:1fr}.ip-cs-rev .ip-cs-img{order:0}.ip-cs-img{min-height:300px}.ip-cs-mini{border-right:0;border-bottom:1px solid var(--line)}.ip-cs-mini:last-child{border-bottom:0}}
@media(max-width:600px){.ip-cs-mini{display:flex;flex-direction:column;gap:.35rem}}

/* Healing Our Land trees */
.ip-trees{background:var(--white)}
.ip-results + .ip-trees{padding-top:0} /* sits straight under the 2025 results on the same white band */
.ip-trees .ip-big{color:var(--euc)}
.ip-trees .ip-big-l{color:var(--euc-deep)}
.ip-trees-num{text-align:right}
.ip-bush-wrap{overflow-x:auto;-webkit-overflow-scrolling:touch}
.ip-bush{min-width:720px}
.ip-bush-art{position:relative}
.ip-bush-art img{display:block;width:100%;height:auto}
.ip-btag{position:absolute;font-size:.78rem;font-weight:700;line-height:1.2;padding:5px 10px;white-space:nowrap}
.ip-btag-d{background:var(--euc-deep);color:var(--cream)}
.ip-btag-now{background:var(--euc-soft);color:var(--euc-deep);transform:translateX(-50%)}
.ip-btag-o{background:var(--white);color:var(--euc-deep);border:1.5px solid var(--euc-deep)}
.ip-baxis{position:relative;height:28px;margin-top:var(--sp-1)}
.ip-baxis span{position:absolute;transform:translateX(-50%);font-family:var(--ff-d);font-weight:700;font-size:.94rem;color:var(--euc-deep)}
.ip-baxis span.on{color:var(--euc-deep)}
.ip-baxis span.now{color:var(--euc)}
.ip-btn-d{background:var(--euc-deep);color:var(--cream);border-color:var(--euc-deep)}
.ip-btn-d:hover{background:var(--euc);border-color:var(--euc);color:var(--cream);opacity:1}
.ip-btn-od{background:transparent;color:var(--euc-deep);border-color:var(--euc-deep)}
.ip-btn-od:hover{background:var(--euc-deep);color:var(--cream);opacity:1}
@media(max-width:700px){.ip-trees-num{text-align:left}}
.ip-trees-top{display:flex;flex-wrap:wrap;gap:var(--sp-5);justify-content:space-between;align-items:flex-end;margin-bottom:var(--sp-5)}
.ip-trees-top .ip-head{max-width:600px}
.ip-big{font-family:var(--ff-d);font-weight:800;font-size:clamp(4rem,8vw,7rem);line-height:1;letter-spacing:-.04em;color:var(--euc-soft)}
.ip-big-l{font-weight:600;color:var(--cream);margin-top:var(--sp-1)}
.ip-trees .ip-acts{margin-top:var(--sp-5)}
@media(max-width:600px){.ip-lt{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-4)}.ip-lt>*:last-child{grid-column:1/-1}}

/* 55 years */
.ip-years-top{display:flex;flex-wrap:wrap;gap:var(--sp-4) var(--sp-6);align-items:flex-end;justify-content:space-between;margin-bottom:var(--sp-5)}
.ip-years-top .ip-head{max-width:520px}
.ip-lt{display:flex;flex-wrap:wrap;gap:var(--sp-5)}
.ip-lt .ip-n{font-size:clamp(3rem,5vw,4.25rem)}
.ip-lt .ip-l{font-size:.94rem;color:var(--stone);max-width:18ch;margin-top:var(--sp-1)}
.ip-rail-wrap{overflow-x:auto;padding:8px 0 4px}
/* one row whatever the number of years: add a year and the columns share the width */
.ip-rail{list-style:none;margin:0;padding:0;display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);min-width:1144px;position:relative}
.ip-rail::before{content:"";position:absolute;left:0;right:0;top:54px;height:3px;background:var(--euc)}
.ip-rail li{display:flex;flex-direction:column;padding-right:14px;position:relative}
.ip-rail b{font-family:var(--ff-d);font-size:clamp(1.3rem,2vw,1.7rem);font-weight:800;letter-spacing:-.03em;color:var(--euc-deep);line-height:1;height:36px;display:flex;align-items:flex-end}
.ip-rail li::after{content:"";position:absolute;left:0;top:47px;width:17px;height:17px;border-radius:50%;background:var(--sand);border:3px solid var(--euc);box-sizing:border-box}
.ip-rail span{margin-top:38px;font-size:.94rem;line-height:1.4;color:var(--char)}
.ip-rail em{display:block;font-style:normal;font-family:var(--ff-d);font-weight:700;color:var(--euc);margin-top:4px}
.ip-rail li.now b{color:var(--euc)}
.ip-rail li.now::after{background:var(--euc-mid);border-color:var(--euc-deep);width:21px;height:21px;top:45px;left:-2px}

/* partner logos (same component as partner.html, no hover pause) */
.ip-partners{background:var(--white)}
.ip-partners .lmq{margin-top:var(--sp-5);display:flex;flex-direction:column;gap:1.6rem;-webkit-mask-image:linear-gradient(to right,transparent 0,#000 7%,#000 93%,transparent 100%);mask-image:linear-gradient(to right,transparent 0,#000 7%,#000 93%,transparent 100%)}
.lmq-row{overflow:hidden}
.lmq-track{display:flex;align-items:center;width:max-content;animation:lmq-scroll var(--dur,72s) linear infinite}
.lmq-track.lmq-rev{animation-direction:reverse}
.lmq:focus-within .lmq-track,.lmq.paused .lmq-track{animation-play-state:paused}
.lmq-i{width:158px;height:58px;flex-shrink:0;margin-right:3.6rem;display:flex;align-items:center;justify-content:center}
.lmq-i img{max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain}
@keyframes lmq-scroll{from{transform:translate3d(0,0,0)}to{transform:translate3d(-50%,0,0)}}
@media (prefers-reduced-motion:reduce){.lmq-track,.hx-tick{animation:none}.lmq-row{overflow-x:auto}}
.lmq-pause{font:inherit;font-size:.78rem;font-weight:600;cursor:pointer;background:transparent;border:1px solid #D9D1C4;color:#0F3132;padding:.35rem .8rem;min-height:36px}
.lmq-row:focus-visible{outline:2px solid var(--euc);outline-offset:2px}
.ip-pause{display:flex;justify-content:flex-end;margin-top:var(--sp-3)}

/* what we can build together next */
.ip-close{position:relative;isolation:isolate;overflow:hidden;background:var(--euc-deep);color:var(--euc-soft)}
.ip-close::before{content:"";position:absolute;inset:0;z-index:-2;background:url('https://elyciap.github.io/fnpw-website-2026/assets/img/bongil.jpg') center/cover;background-image:image-set(url('https://elyciap.github.io/fnpw-website-2026/assets/img/r/bongil-1600.webp') type('image/webp'),url('https://elyciap.github.io/fnpw-website-2026/assets/img/bongil.jpg') type('image/jpeg'))}
.ip-close::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(100deg,rgba(15,49,50,.96) 0%,rgba(15,49,50,.86) 45%,rgba(15,49,50,.6) 100%)}
.ip-close h2{color:var(--cream)}
.ip-close .ey{color:var(--euc-mid)}
.ip-close .lede{color:rgba(250,246,242,.9)}
.ip-close-top{display:flex;flex-wrap:wrap;gap:var(--sp-5);align-items:center}
.ip-close-ctas{display:flex;flex-wrap:wrap;gap:.75rem;margin-top:var(--sp-4)}
.ip-close-ctas .btn{font-weight:600}
.ip-close-top .ip-head{flex:1 1 360px;max-width:460px}
.ip-goals{flex:1 1 480px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-2)}
.ip-goal{background:rgba(15,49,50,.62);border:1px solid rgba(198,235,202,.3);padding:var(--sp-3);display:flex;flex-direction:column;gap:var(--sp-1)}
.ip-goal.big{grid-column:1 / -1;background:rgba(15,119,104,.6)}
.ip-goal b{font-family:var(--ff-d);font-weight:800;font-size:clamp(2.5rem,4.4vw,3.75rem);line-height:1;letter-spacing:-.04em;color:var(--cream)}
.ip-goal.big b{font-size:clamp(3.5rem,6vw,5.25rem)}
.ip-goal b small{font-family:var(--ff-b);font-size:1.25rem;font-weight:700;letter-spacing:0;color:var(--euc-soft);margin-left:.3em}
.ip-goal span{font-size:.94rem;line-height:1.45;color:var(--euc-soft)}
@media(max-width:600px){.ip-goals{grid-template-columns:1fr}}

.piw{font-family:'Figtree',sans-serif;font-size:17px;line-height:1.65;color:#241914;background:#FAF6F2;-webkit-font-smoothing:antialiased}
.piw *{box-sizing:border-box}
.piw h1,.piw h2,.piw h3,.piw h4{font-family:'Sora',sans-serif;font-weight:600;line-height:1.1;letter-spacing:-.022em;color:#0F3132;margin:0}
.piw h1{font-size:clamp(2.3rem,4.6vw,3.8rem);letter-spacing:-.03em;line-height:1.04}
.piw h2{font-size:clamp(1.6rem,3vw,2.4rem);letter-spacing:-.02em}
.piw h3{font-size:clamp(1.05rem,1.5vw,1.25rem)}
.piw p{margin:0 0 1em}.piw p:last-child{margin-bottom:0}
.piw ul{margin:0;padding:0;list-style:none}
.cw{max-width:1240px;margin:0 auto;padding:0 clamp(1.25rem,4vw,2.5rem);position:relative}
.sec{padding:var(--sec-md) 0;position:relative}
.sand{background:#EEE8E1}
.dark{background:#0F3132;color:#C6EBCA}
.dark h1,.dark h2,.dark h3{color:#FAF6F2}
.ey{font-size:.75rem;font-weight:700;letter-spacing:.22em;text-transform:uppercase;color:var(--euc-deep);display:inline-flex;align-items:center;gap:.6em;margin-bottom:1rem}
