(function(){
  [].forEach.call(document.querySelectorAll('.piw [role="tablist"]'),function(list){
    var tabs=[].slice.call(list.querySelectorAll('[role="tab"]'));
    function sel(t,focus){
      tabs.forEach(function(x){var on=x===t;x.setAttribute('aria-selected',on?'true':'false');x.tabIndex=on?0:-1;document.getElementById(x.getAttribute('aria-controls')).hidden=!on});
      if(focus)t.focus();
    }
    tabs.forEach(function(t,i){
      t.addEventListener('click',function(){sel(t)});
      t.addEventListener('keydown',function(e){
        var n=null,k=e.key;
        if(k==='ArrowRight'||k==='ArrowDown')n=tabs[(i+1)%tabs.length];
        else if(k==='ArrowLeft'||k==='ArrowUp')n=tabs[(i-1+tabs.length)%tabs.length];
        else if(k==='Home')n=tabs[0];else if(k==='End')n=tabs[tabs.length-1];
        if(n){e.preventDefault();sel(n,true)}
      });
    });
  });
