meta._fnpw_page_js:
const PD=[]; /* old 16-project popup data retired Nov 2026: project cards link to their own pages */
const PN={parks:"Growing Parks",species:"Saving Species",heal:"Healing Our Land"};
const _fmeta=document.getElementById('fmeta'),_empty=document.getElementById('pempty'),
      _search=document.getElementById('psearch'),_searchx=document.getElementById('psearchx');
let _pillar='all',_state='all';
const _stMeta=document.getElementById('imStMeta');
const STATE_NAME={NSW:'New South Wales',VIC:'Victoria',QLD:'Queensland',SA:'South Australia',WA:'Western Australia',TAS:'Tasmania',NT:'the Northern Territory',ACT:'the ACT',Australia:'Australia-wide programs'};
function applyFilters(){
  const q=(_search.value||'').trim().toLowerCase();
  let c=0;
  document.querySelectorAll('#pgrid .pc').forEach(x=>{
    const okPillar = _pillar==='all' || x.dataset.pil===_pillar;
    const okState  = _state==='all' || x.dataset.state===_state;
    const okQuery  = !q || (x.dataset.search||'').indexOf(q)>-1;
    const show = okPillar && okState && okQuery;
    x.style.display = show ? '' : 'none';
    if(show) c++;
  });
  const total=document.querySelectorAll('#pgrid .pc').length;
  const where = _state==='all' ? '' : ` in ${STATE_NAME[_state]||_state}`;
  _fmeta.textContent = (!q && _pillar==='all' && _state==='all')
    ? `Showing all ${total} projects`
    : `Showing ${c} project${c===1?'':'s'}${where}${q?` for \u201c${_search.value.trim()}\u201d`:''}`;
  if(_empty) _empty.hidden = c!==0;
  if(_searchx) _searchx.hidden = !q;
  if(_stMeta){
    _stMeta.innerHTML = _state==='all' ? '' :
      `${c} project${c===1?'':'s'}${where}. <a href="#projectsGrid">Jump to the list</a>`;
  }
}
document.querySelectorAll('#fps .fp').forEach(b=>b.addEventListener('click',()=>{
  document.querySelectorAll('#fps .fp').forEach(p=>p.classList.remove('on'));b.classList.add('on');
  _pillar=b.dataset.f; applyFilters();
}));
/* state picker (phones): same list, filtered by state */
function setState(st){
  _state=st;
  document.querySelectorAll('#imStates .im-st').forEach(b=>{
    const on=b.dataset.st===st; b.classList.toggle('on',on); b.setAttribute('aria-pressed',on?'true':'false');
  });
  applyFilters();
}
document.querySelectorAll('#imStates .im-st').forEach(b=>b.addEventListener('click',()=>setState(b.dataset.st)));
/* the picker is only shown under 700px; if the window grows past that, drop the state filter so no hidden control is left applied */
const _mqStates=window.matchMedia('(min-width:700px)');
_mqStates.addEventListener('change',e=>{if(e.matches&&_state!=='all')setState('all');});
/* scroll hint on the pill row */
const _fps=document.getElementById('fps');
function fpsHint(){if(_fps)_fps.classList.toggle('more',_fps.scrollWidth-_fps.clientWidth-_fps.scrollLeft>4);}
if(_fps){_fps.addEventListener('scroll',fpsHint,{passive:true});window.addEventListener('resize',fpsHint);fpsHint();}
_search.addEventListener('input',applyFilters);
_search.addEventListener('keydown',e=>{if(e.key==='Escape'){_search.value='';applyFilters();}});
if(_searchx) _searchx.addEventListener('click',()=>{_search.value='';applyFilters();_search.focus();});
const _sgo=document.getElementById('psearchgo');
if(_sgo) _sgo.addEventListener('click',()=>{applyFilters();const g=document.getElementById('projectsGrid');if(g&&window.innerWidth<900)g.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'start'});});
const _pclear=document.getElementById('pclear');
if(_pclear) _pclear.addEventListener('click',()=>{
  _search.value='';
  document.querySelectorAll('#fps .fp').forEach(p=>p.classList.toggle('on',p.dataset.f==='all'));_pillar='all';
  setState('all');_search.focus();
});
const _grid=document.getElementById('pgrid');
[..._grid.querySelectorAll('.pc')].forEach((c,i)=>{
  c.dataset.idx=i;
  c.dataset.title=(c.querySelector('h3').textContent||'').trim();
  const loc=c.querySelector('.pc-lo'), pil=c.querySelector('.pc-pb');
  c.dataset.search=[c.dataset.title, loc?loc.textContent:'', pil?pil.textContent:''].join(' ').toLowerCase();
});
document.getElementById('psort').addEventListener('change',e=>{
  const mode=e.target.value;
  [..._grid.querySelectorAll('.pc')].sort((a,b)=>{
    if(mode==='az')return a.dataset.title.localeCompare(b.dataset.title,'en',{numeric:true,sensitivity:'base'});
    if(mode==='oldest')return (+b.dataset.idx)-(+a.dataset.idx);
    return (+a.dataset.idx)-(+b.dataset.idx);
  }).forEach(c=>_grid.appendChild(c));
});
const po=document.getElementById('po'),ppx=document.getElementById('ppx');
function op(id){const p=PD.find(x=>x.id===id);if(!p)return;document.getElementById('ppi').src=p.img;document.getElementById('ppi').alt=p.name;document.getElementById('pph').textContent=p.name;document.getElementById('ppt').textContent=PN[p.pil]+' · '+p.loc;document.getElementById('pps').innerHTML=p.stats.map(s=>`<div class="ps"><strong>${s[0]}</strong><span>${s[1]}</span></div>`).join('');document.getElementById('ppc').innerHTML=p.body;po.classList.add('open');document.body.style.overflow='hidden'}
function cp(){po.classList.remove('open');document.body.style.overflow=''}
document.querySelectorAll('.pc').forEach(c=>c.addEventListener('click',()=>op(c.dataset.id)));
ppx.addEventListener('click',cp);po.addEventListener('click',e=>{if(e.target===po)cp()});document.addEventListener('keydown',e=>{if(e.key==='Escape')cp()});
window.addEventListener('load',()=>{if(location.hash){const id=location.hash.slice(1);if(PD.find(p=>p.id===id))op(id)}});

