.gw-how .fine{margin-top:1.4rem;font-size:.92rem;color:rgba(250,246,242,.86);max-width:76ch}
.gw-how .fine a{color:var(--wattle-soft);font-weight:600}
/* wording */
.gw-word{padding:var(--sec-md) 0;background:var(--cream)}
.gw-word-g{display:grid;grid-template-columns:minmax(0,7fr) minmax(0,5fr);gap:clamp(2rem,4vw,3.5rem);align-items:start}
