@media(max-width:900px){.gw-strip-g{grid-template-columns:1fr}}
.gw-sb{display:flex;gap:1.3rem;align-items:center;background:#fff;padding:1.3rem 1.4rem;text-decoration:none;color:var(--char);border:1px solid var(--rule)}
