.gw-form .priv{font-size:.82rem;color:var(--stone);margin-top:1rem}.gw-form .priv a{text-decoration:underline}
.gw-form a{color:var(--euc)}
/* faqs */
.gw-faq{padding:var(--sec-md) 0;background:var(--cream)}
