.hs-form-frame{min-height:420px}.hsform-fallback{font-size:.92rem;line-height:1.6;color:var(--char);background:var(--sand);padding:1rem 1.2rem;margin-top:1rem}.hsform-fallback a{color:var(--euc);text-decoration:underline}
